<script>
document.addEventListener('DOMContentLoaded',()=>{
 const form=document.getElementById('direct-receipt-form');if(!form)return;
 const lines=document.getElementById('receipt-lines'),source=document.getElementById('receipt-source'),status=document.getElementById('receipt-search-status'),results=document.getElementById('receipt-results'),search=document.getElementById('receipt-search');let index=0;
 const sync=()=>{const invoice=source.value==='invoice';form.elements.invoice_reference.required=invoice;form.elements.invoice_date.required=invoice;form.elements.invoice_reference.disabled=!invoice;form.elements.invoice_date.disabled=!invoice;lines.querySelectorAll('select').forEach(s=>{s.disabled=!invoice;if(!invoice)s.value='';});};
 const add=(item)=>{if(lines.querySelector('[data-row="'+Number(item.row_id)+'"]')){status.textContent='สินค้านี้มีแล้ว กรุณาปรับจำนวนในรายการเดิม';return;}const node=document.getElementById('receipt-line-template').content.firstElementChild.cloneNode(true);node.dataset.row=Number(item.row_id);node.querySelector('.line-label').textContent=item.label;node.querySelectorAll('[data-field]').forEach(el=>{el.name='lines['+index+']['+el.dataset.field+']';if(item[el.dataset.field]!=null)el.value=item[el.dataset.field];});node.querySelector('.remove-line').addEventListener('click',()=>node.remove());lines.append(node);index++;sync();};
 const lookup=async()=>{const term=search.value.trim();if(!term)return;results.replaceChildren();status.textContent='กำลังค้นหา…';try{const url=new URL({{ \Illuminate\Support\Js::from(route('ns.goods-receipts.index')) }});url.searchParams.set('branch_id',{{ $branch }});url.searchParams.set('lookup','1');url.searchParams.set('q',term);const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error();const rows=await response.json();status.textContent=rows.length?'เลือกสินค้าและหน่วยที่รับ (แสดงไม่เกิน 30 รายการ)':'ไม่พบหน่วยสินค้าในสาขานี้ กรุณาตรวจชื่อหรือเพิ่มสินค้าสาขาก่อน';rows.forEach(row=>{const button=document.createElement('button');button.type='button';button.textContent=row.name+' — '+row.unit;button.addEventListener('click',()=>{add({row_id:row.id,label:button.textContent,quantity:1,price:''});results.replaceChildren();search.value='';search.focus();});results.append(button);});}catch(e){status.textContent='ค้นหาไม่สำเร็จ กรุณาลองใหม่';}};
 document.getElementById('receipt-search-button').addEventListener('click',lookup);search.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();lookup();}});source.addEventListener('change',sync);form.addEventListener('submit',e=>{if(!lines.children.length){e.preventDefault();status.textContent='กรุณาเพิ่มสินค้าอย่างน้อยหนึ่งรายการ';}});
 Object.values({{ \Illuminate\Support\Js::from(old('lines',[])) }}).forEach(add);sync();
});
</script>
